{
  "findings": [
    {
      "check_id": "CKV_AZURE_70",
      "title": "Function App does not enforce HTTPS",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "HIGH",
      "explanation": "The Function App does not set https_only, allowing clients to connect over unencrypted HTTP and potentially expose sensitive request data in transit."
    },
    {
      "check_id": "CKV_AZURE_71",
      "title": "Function App has no managed identity",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "No managed identity is configured, preventing the Function App from using Azure AD token-based authentication when accessing supported Azure services."
    },
    {
      "check_id": "CKV_AZURE_78",
      "title": "FTP deployments are enabled",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "HIGH",
      "explanation": "The site configuration does not disable FTP deployments, leaving a credential-based deployment interface available and potentially permitting unencrypted FTP connections."
    }
  ],
  "patched_code": "resource \"azurerm_function_app\" \"changeme_simple_function_app\" {\n  name                       = \"changeme-simple-function-app-name\"\n  location                   = azurerm_resource_group.changeme_simple_function_app_resource_group.location\n  resource_group_name        = azurerm_resource_group.changeme_simple_function_app_resource_group.name\n  app_service_plan_id        = azurerm_app_service_plan.changeme_simple_function_app_app_service_plan.id\n  storage_account_name       = azurerm_storage_account.changeme_simple_function_app_storage_account.name\n  storage_account_access_key = azurerm_storage_account.changeme_simple_function_app_storage_account.primary_access_key\n  https_only                 = true\n\n  identity {\n    type = \"SystemAssigned\"\n  }\n\n  site_config {\n    ftps_state = \"Disabled\"\n  }\n}\n",
  "fix_summary": "Enforced HTTPS, enabled a system-assigned managed identity, and disabled FTP-based deployments. All existing resource properties were retained."
}
